 b:=u8[1];mut x=0;if false{x=1;}else if true{x=2;}assert(x==2);println(42);}

struct Point{x:i32,y:i32}
impl Point{fn sum<a>(self:(&a Point))->i32{return self.x+self.y;}fn shift<a>(self:(&a mut Point),dx:i32){self.x=self.x+dx;}}
struct Shape{origin:Point,size:u64}
impl Shape{fn moved<a>(self:(&a mut Shape)){self.origin.shift(5);}fn total<a>(self:(&a Shape))->i32{return self.origin.sum();}}
fn main(){mut s=Shape{origin:Point{x:1,y:2},size:3};assert(s.origin.sum()==3);s.origin.shift(1);assert(s.origin.sum()==4);s.moved();assert(s.total()==9);println(42);}

