impl Point{fn new(x:i32,y:i32)->Point{return Point{x:x,y:y};}fn sum<a>(self:(&a Point))->i32{return self.x+self.y;}fn grow<a>(self:(&a mut Point))->i32{self.x=self.x+1;return self.x;}}
struct Bag{items:u8[][]}
impl Bag{fn make()->Bag{return Bag{items:u8[][u8[1],u8[2]]};}fn count<a>(self:(&a Bag))->u64{return self.items.len();}}
fn main(){assert(Point::new(1,2).sum()==3);assert(Point::new(5,0).grow()==6);assert(Bag::make().count()==2);println(42);}

use core;
fn first(v:u64[])->u64?{if v.len()==0{return None;}return Some(v[0]);}
fn label(o:u8[]?)->u64{if let Some(b) = o {return b.len();} else {return 0;}}
fn main(){
    if let Some(x) = first(u64[7,8]) {assert(x==7);} else {assert(false);}
    if let Some(x) = first(u64[]) {assert(false);}
    assert(label(Some(u8[1,2,3]))==3);assert(label(None)==0);
    r: u64? := None;if let Some(v) = r {assert(false);} else if true {println(42);}
}

use core;
fn pop<a>(v:(&a mut u8[][]))->u8[]?{if v.len()==0{return None;}return Some(v.pop());}
fn main(){
    mut stack=u8[][u8[1],u8[2,2],u8[3,3,3]];mut total=0;
    while let Some(item) = pop(&mut stack) {total+=item.len();}
    assert(total==6);
    mut n=0;mut more=u8[][u8[1],u8[2]];
    while let Some(x) = pop(&mut more) {n+=1;if n==1{break;}}
    assert(n==1);println(42);
}

fn count_slashes<a>(path:&a [u8])->u64{mut n=0;for b in path{if b=='/'{n+=1;}}return n;}
