enum Shape{Circle(u64),Square(u64),Empty}
impl Shape{
    fn area<a>(self:(&a Shape))->u64{match self{Circle(r)=>{return 3*r*r;},Square(s)=>{return s*s;},Empty=>{return 0;}}}
