struct Version{major:u64,minor:u64}
impl order::Ord for Version{fn less<a,b>(left:(&a Self),right:(&b Self))->bool{if left.major!=right.major{return left.major<right.major;}return left.minor<right.minor;}}
interface Area{fn area<a>(shape:(&a Self))->u64;}
struct Square{side:u64}
impl Area for Square{fn area<a>(shape:(&a Self))->u64{return shape.side*shape.side;}}
