struct P { x: u64, name: string }
fn make(n: u64) -> P { return P { x: n, name: "p".text() }; }
fn total<a>(v: &a [u8]) -> u64 { return v.len(); }
fn get_x<a>(p: (&a P)) -> u64 { return p.x; }
fn bump<a>(p: (&a mut P)) { n := p.x + 1; exchange(&mut p.x, n); }
impl P { fn label<a>(self: (&a P)) -> u64 { return self.x * 2; } }
fn main() {
    println(get_x(&make(4)));
    r := &make(7);
    println(r.x);
    for x in &u64[1, 2, 3] { print(x); }
    println();
    m := &mut make(1);
    bump(&mut m);
    println(m.x);
    q := make(9);
    println(get_x(&q));
    l := &q.label();
    println(l);
}

