enum Slot { Empty, Full(u64) }
fn main() {
    mut s = Slot::Full(3);
    mut count = 0;
    match &s {
        Full(n) => {
            count = n + 1;
            s = Slot::Empty;
        },
        Empty => {
            s = Slot::Full(1);
        }
    }
    println(count);
}

enum Slot { Empty, Full(u8[]) }
