    mut s = Slot::Full(u8[1, 2]);
    match &s {
        Full(b) => {
            s = Slot::Empty;
            println(b.len());
        },
        Empty => {},
    }
}

enum Slot { Empty, Full(u8[]) }
fn main() {
    mut s = Slot::Full(u8[1, 2]);
    match &mut s {
        Full(b) => {
            b.push(3);
            println(b.len());
            s = Slot::Empty;
        },
        Empty => { s = Slot::Full(u8[]); },
    }
    match &s { Full(b) => { println(b.len()); }, Empty => { println(0); } }
}

