// A sized integer keeps its stated signedness inside an `unsafe module`, whose other values are
// untyped words: 0 - 1 is -1, the comparison against 0 is signed, i8 120 + 7 stops at 127.
// The `extern "C"` declaration carries a `cfn` parameter, the shape the report named.
unsafe module runtime;
extern "C" lib "c" fn qsort(base: u64, n: u64, size: u64, cmp: cfn(u64, u64) -> i32) -> unit;
fn main() {
    mut x: i32 = 0;
    x = x - 1;
    println(x);
    println(x < 0);
    mut small: i8 = 120;
    small = small + 7;
    println(small);
    mut wide: i64 = 0;
    wide = wide - 1;
    println(wide < 0);
}

