fn hexval(ch: u8) -> u8 {
    if ch < 58 {
        return ch - 48;
    }
    return ch - 87;
}
fn unhex<a>(text: &a [u8]) -> u8[] {
    mut out = u8[];
    mut i: u64 = 0;
    while i + 1 < text.len() {
        out.push(hexval(text[i]) * 16 + hexval(text[i + 1]));
        i += 2;
    }
    return out;
}
fn main() {
    b := unhex("4a2f");
    println(b[0] + b[1]);
}

