}
fn run(n: u64) -> u64 {
    mut d = D { out: u8[] };
    mut v = u8[1];
    while n > 9 {
        return 7;
    }
    for i in n {
        if i > 100 {
            continue;
        }
        return 8;
    }
    v.push(2);
    out := exchange(&mut d.out, u8[]);
