use vecs;
struct G { depth: u64, terminal: bool, id: u64 }
fn before<a, b>(x: (&a G), y: (&b G)) -> bool {
    if x.terminal != y.terminal {
        return x.terminal;
    }
    return x.depth > y.depth;
}
fn mod4<a>(x: (&a u64)) -> u64 {
    return *x % 4;
}
fn main() {
    mut g = G[G { depth: 1, terminal: false, id: 0 }, G { depth: 3, terminal: true, id: 1 }, G { depth: 2, terminal: false, id: 2 }, G { depth: 3, terminal: false, id: 3 }, G { depth: 1, terminal: true, id: 4 }, G { depth: 2, terminal: false, id: 5 }];
    // terminal first, then deeper first; stable
    vecs::sort_by(&mut g, before);
    for e in &g { print("{} ", e.id); }
    println("");
    mut w = u64[5, 3, 9, 3, 1];
    vecs::sort_by_key(&mut w, mod4);
    println("{}", w);
    mut f = f32[2.5, -1.0, 0.5];
    vecs::sort(&mut f);
    println("{}", f);
    mut set = u64[];
    for x in u64[7, 3, 7, 1, 9, 3] { vecs::insert_sorted(&mut set, x); }
    println("{}", set);
    for q in u64[9, 4] {
        match vecs::binary_search(&set, &q) {
            Some(i) => { println("{} at {}", q, i); },
            None => { println("{} absent", q); }
        }
    }
}

