use net;
use io;
fn client(port: u64, unused: u64) -> u64 {
    mut stream = net::connect("127.0.0.1", port)!;
    assert(stream.write_all(view("ping")));
    stream.close();
    return 1;
}
fn refused(port: u64) -> bool {
    match net::connect("127.0.0.1", port) {
        accepted: net::TcpStream => { accepted.close(); return false; },
        error: io::Error => { return true; }
    }
}
fn body<s>(sc: (&s Scope<u64>), count: u64) -> u64 {
    listener := net::bind("127.0.0.1", 0)!;
    port := listener.port();
    assert(port > 0);
    peer := spawn(sc, port, client);
    mut stream = listener.accept()!;
    mut head = u8[0; 4];
    count := stream.read(&mut head);
    assert(count > 0);
    mut data = u8[];
    for i in count { data.push(head[i]); }
    for b in stream.read_all() { data.push(b); }
    assert(stream.write_all(view("pong")));
    stream.close();
    assert(join(peer) == 1);
    listener.close();
    println(data.text());
    assert(refused(port));
    match net::connect("not an address", 80) {
        accepted: net::TcpStream => { accepted.close(); assert(false); },
        error: io::Error => { println(error.show()); }
    }
    return data.len();
}
fn main(){
    assert(task_scope(2, body) == 4);
}

