fn largest<S: Source>(s: &mut S) -> S::Item? {
    mut best: S::Item? = None;
    while let Some(x) = s.pull() {
        match best {
            Some(b) => {
                if b < x {
                    best = Some(x);
                } else {
                    best = Some(b);
                }
            },
            None => {
                best = Some(x);
            },
        }
    }
    return best;
}
