use host;
// 100k tasks spawned before the first join: the deque (or the injection ring behind it) has to hold
// a burst that is much larger than one worker's stack cache, and every result must still arrive.
fn unit(n: u64, unused: u64) -> u64 {
    return (n * 2654435761) % 1000003;
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    mut many = Task<u64>[];
    for i in 100000 {
        many.push(spawn(sc, i, unit));
    }
    mut total = 0;
    while many.len() != 0 {
        total += join(many.pop());
    }
    return total;
}
fn main() {
    println(task_scope(0, body));
}

use host;
struct Ctx {
    started: Atomic<u64>
}
// The barrier is what makes the spread a fact rather than a hope: a task that starts spins until a
// second task has started, and a spinning task occupies its worker, so the second one must be on a
// different worker (the floor in rt_os_workers guarantees at least two exist).
fn work(n: u64, c: (&Ctx)) -> u64 {
    c.started.fetch_add(1);
    while c.started.load() < 2 {}
    mut total = 0;
    for i in n {
        total += i % 7;
    }
    return total * 64 + (host::worker_id() & 63);
}
fn body<s>(sc: (&s Scope<(&Ctx)>), c: (&Ctx)) -> u64 {
    mut many = Task<u64>[];
    for i in 8 {
        many.push(spawn(sc, 4000, work));
    }
    mut total = 0;
    mut ids = 0;
    while many.len() != 0 {
        r := join(many.pop());
        total += r / 64;
        ids = ids | (r % 64);
    }
    mut distinct = 0;
    mut m = ids;
    for i in 64 {
        distinct += m & 1;
        m = m / 2;
    }
    assert(0 < distinct);
    if 1 < host::workers() {
        assert(1 < distinct);
    }
    return total;
}
fn main() {
    println(task_scope(&Ctx { started: Atomic::new(0) }, body));
}

use host;
// Eight sleeping tasks must overlap: a serial sleep would take 8 * 30 ms, and the assertion below
// fails long before that.
fn nap(n: u64, unused: u64) -> u64 {
    host::sleep_ms(30);
    return n;
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    mut many = Task<u64>[];
    for i in 8 {
        many.push(spawn(sc, i, nap));
    }
    mut total = 0;
    while many.len() != 0 {
        total += join(many.pop());
    }
    return total;
}
fn main() {
    start := host::now_ms();
    println(task_scope(0, body));
    elapsed := host::now_ms() - start;
    assert(elapsed < 400);
}

// A fork-join tree four levels deep, spawned from tasks that are themselves stolen: 2048 leaves
// cross the deques, which is where a Chase-Lev push/pop/steal race shows up as a lost or duplicated
// task (the checksum changes) rather than as a crash.
fn leaf(n: u64, unused: u64) -> u64 {
    mut x = n;
    for i in 100 {
        x = (x * 31 + 7) % 1000003;
    }
    return x;
}
fn level(n: u64, unused: u64) -> u64 {
    if n == 0 {
        return leaf(1, 0);
    }
    return task_scope(n, tree);
}
fn tree<s>(sc: (&s Scope<u64>), n: u64) -> u64 {
    mut many = Task<u64>[];
    for i in 4 {
        many.push(spawn(sc, n - 1, level));
    }
    mut total = 0;
    while many.len() != 0 {
        total += join(many.pop());
    }
    return total;
}
fn main() {
    mut total = 0;
    for i in 8 {
        total += level(4, 0);
    }
    println(total);
}

