// Deep recursion inside a task runs into the guard page at the bottom of its stack. The fault is
// recognised as a task-stack overflow and reported once, by name, with status 134 - not as a silent
// write into the neighbouring mapping and not as an unexplained SIGSEGV.
fn deep(n: u64, unused: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    return deep(n - 1, 0) + 1;
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    t := spawn(sc, 1000000, deep);
    return join(t);
}
fn main() {
    println("before");
    println(task_scope(0, body));
}

